    // -- Ticket 48: tray dispatch + fetch guards ---------------------------

    /// Ticket 48 (US-62): every tray menu id dispatches headless to its
    /// handler — StartAll serves the library, StopAll stops it, Show is a
    /// windowing no-op that never touches the engine, Quit stops +
    /// clears + drops. Foreign ids map to nothing (tray.rs). Windowing
    /// itself stays manual-tour only.
    #[gpui_kit::test]
    fn t48_tray_dispatch_every_menu_id_runs_its_handler(cx: &mut TestAppContext) {
        use crate::engine::EngineController;
        use crate::tray::{action_for_menu_id, menu_id, TrayAction};

        cx.update(gpui_kit::init);

        let mut store = Store::open_in_memory().expect("in-memory store opens");
        let alpha = store
            .add(tick12_seed("Alpha", "10871"))
            .expect("seed works");
        let beta = store.add(tick12_seed("Beta", "10872")).expect("seed works");

        let (view, cx) = mount_view(store, cx);
        cx.update(|_, cx| {
            view.update(cx, |view, _| {
                let (engine, _) = EngineController::fake();
                view.engine = engine;
            });
        });

        // The wall: every known id maps to exactly one action, foreign
        // ids map to nothing and never reach a handler.
        for (id, action) in [
            (menu_id::SHOW, TrayAction::Show),
            (menu_id::START_ALL, TrayAction::StartAll),
            (menu_id::STOP_ALL, TrayAction::StopAll),
            (menu_id::QUIT, TrayAction::Quit),
        ] {
            assert_eq!(action_for_menu_id(id), Some(action), "id {id} dispatches");
            assert_eq!(
                crate::tray::menu_id_for_action(action),
                id,
                "id {id} round-trips"
            );
        }
        assert_eq!(action_for_menu_id("foreign-id"), None);

        cx.update(|window, cx| {
            view.update(cx, |view, cx| {
                view.handle_tray_action(TrayAction::StartAll, window, cx)
            });
        });
        cx.run_until_parked();
        assert_eq!(
            view.read_with(cx, |view, _| view.engine.running_count()),
            2,
            "StartAll serves the library"
        );
        let mut snapshot = view.read_with(cx, |view, _| view.store.load_running_snapshot());
        snapshot.sort();
        let mut expected = vec![alpha.id.clone(), beta.id.clone()];
        expected.sort();
        assert_eq!(snapshot, expected, "snapshot names the serving set");

        cx.update(|window, cx| {
            view.update(cx, |view, cx| {
                view.handle_tray_action(TrayAction::Show, window, cx)
            });
        });
        assert_eq!(
            view.read_with(cx, |view, _| view.engine.running_count()),
            2,
            "Show never touches the engine"
        );

        cx.update(|window, cx| {
            view.update(cx, |view, cx| {
                view.handle_tray_action(TrayAction::StopAll, window, cx)
            });
        });
        // Ticket-43 semantics: StopAll dispatches into the confirm gate —
        // the dialog opens, nothing stops until the user confirms.
        assert_eq!(
            view.read_with(cx, |view, _| view.engine.running_count()),
            2,
            "confirm gates the kill"
        );
        assert!(
            cx.update(|window, cx| window.has_active_dialog(cx)),
            "StopAll dispatch opens the confirm"
        );
        cx.update(|window, cx| window.close_all_dialogs(cx));
        cx.update(|window, cx| {
            view.update(cx, |view, cx| view.commit_stop_all(window, cx));
        });
        assert_eq!(
            view.read_with(cx, |view, _| view.engine.running_count()),
            0,
            "confirmed StopAll stops every endpoint"
        );
        assert!(
            view.read_with(cx, |view, _| view.store.load_running_snapshot())
                .is_empty(),
            "stop clears the snapshot"
        );

        // Quit from a serving state: engine stopped, snapshot cleared,
        // icon dropped — the caller then quits the app.
        cx.update(|window, cx| {
            view.update(cx, |view, cx| {
                view.handle_tray_action(TrayAction::StartAll, window, cx)
            });
        });
        assert_eq!(view.read_with(cx, |view, _| view.engine.running_count()), 2);
        cx.update(|window, cx| {
            view.update(cx, |view, cx| {
                view.handle_tray_action(TrayAction::Quit, window, cx)
            });
        });
        assert_eq!(
            view.read_with(cx, |view, _| view.engine.running_count()),
            0,
            "Quit stops the engine"
        );
        assert!(
            view.read_with(cx, |view, _| view.store.load_running_snapshot())
                .is_empty(),
            "Quit clears the snapshot"
        );
        assert!(
            view.read_with(cx, |view, _| view.tray.is_none()),
            "Quit drops the icon"
        );
    }

    /// Ticket 48 (US-66): redirect resolution table — absolute http(s)
    /// URLs pass through for the policy re-check, origin-absolute paths
    /// resolve against the current origin, everything else is refused.
    #[test]
    fn t48_resolve_fetch_redirect_table() {
        use crate::{is_fetch_redirect, resolve_fetch_redirect};
        use gpui_kit::http_client::http::StatusCode;
        for code in [301u16, 302, 303, 307, 308] {
            assert!(
                is_fetch_redirect(StatusCode::from_u16(code).expect("status builds")),
                "{code} follows by hand"
            );
        }
        for code in [200u16, 204, 404, 500] {
            assert!(
                !is_fetch_redirect(StatusCode::from_u16(code).expect("status builds")),
                "{code} is not a redirect"
            );
        }
        assert_eq!(
            resolve_fetch_redirect(
                "https://example.com/sub.txt",
                "https://cdn.example.com/sub.txt"
            ),
            Some("https://cdn.example.com/sub.txt".to_string())
        );
        assert_eq!(
            resolve_fetch_redirect("https://example.com/a/sub.txt", "/b/sub.txt"),
            Some("https://example.com/b/sub.txt".to_string())
        );
        assert_eq!(
            resolve_fetch_redirect("https://example.com:8443/a", "/b"),
            Some("https://example.com:8443/b".to_string())
        );
        // Refused, never guessed: relative segments, other schemes,
        // empties, and unparsable currents.
        for (current, location) in [
            ("https://example.com/a", "b/sub.txt"),
            ("https://example.com/a", "../sub.txt"),
            ("https://example.com/a", "ftp://example.com/sub.txt"),
            ("https://example.com/a", "file:///etc/passwd"),
            ("https://example.com/a", ""),
            ("https://example.com/a", "   "),
            ("not-a-url", "/b"),
            ("https://", "/b"),
        ] {
            assert_eq!(
                resolve_fetch_redirect(current, location),
                None,
                "refused: {current:?} + {location:?}"
            );
        }
    }

    /// Ticket 41: save-gate passthrough vs refusal — blank, whitespace-only,
    /// unparseable, and auto ports flow through Ok (store validation owns
    /// those errors); reserved ports and garbage binds fail with the named
    /// reason before any write.
    #[test]
    fn t41_save_listen_gate_passthrough_and_refusal() {
        assert_eq!(crate::save_listen_gate("Row", "127.0.0.1", ""), Ok(()));
        assert_eq!(crate::save_listen_gate("Row", "127.0.0.1", "   "), Ok(()));
        assert_eq!(
            crate::save_listen_gate("Row", "127.0.0.1", "not-a-port"),
            Ok(())
        );
        assert_eq!(crate::save_listen_gate("Row", "127.0.0.1", "0"), Ok(()));
        assert_eq!(crate::save_listen_gate("Row", "127.0.0.1", "10801"), Ok(()));
        assert_eq!(crate::save_listen_gate("Row", "", "10801"), Ok(()));
        let err =
            crate::save_listen_gate("Row", "127.0.0.1", "18501").expect_err("clash range refused");
        assert!(
            err.contains("clash-controller range 18501-18999"),
            "names range, got {err}"
        );
        let err =
            crate::save_listen_gate("Row", "127.0.0.1", "11801").expect_err("bridge range refused");
        assert!(
            err.contains("xray-bridge range 11801-11999"),
            "names range, got {err}"
        );
        let err = crate::save_listen_gate("Row", "999.999.0.1", "10801")
            .expect_err("garbage bind refused");
        assert!(err.contains("bad bind address"), "names bind, got {err}");
    }

    /// Ticket 48: redirect-resolution edges — trims whitespace, preserves
    /// absolute casing verbatim, keeps the query on origin-absolute hops,
    /// keeps protocol-relative targets same-origin, refuses single-slash
    /// and script targets; non-redirect statuses never follow.
    #[test]
    fn t48_resolve_fetch_redirect_edges() {
        use crate::{is_fetch_redirect, resolve_fetch_redirect};
        use gpui_kit::http_client::http::StatusCode;
        assert_eq!(
            resolve_fetch_redirect("https://example.com/a/sub.txt", "  /b/sub.txt  "),
            Some("https://example.com/b/sub.txt".to_string())
        );
        assert_eq!(
            resolve_fetch_redirect("https://example.com/a", "HTTPS://cdn.example.com/sub.txt"),
            Some("HTTPS://cdn.example.com/sub.txt".to_string())
        );
        assert_eq!(
            resolve_fetch_redirect("https://example.com:8443/a/b?x=1", "/c?y=2"),
            Some("https://example.com:8443/c?y=2".to_string())
        );
        assert_eq!(
            resolve_fetch_redirect("https://example.com/a", "//evil.com/x"),
            Some("https://example.com//evil.com/x".to_string())
        );
        assert_eq!(
            resolve_fetch_redirect("https://example.com/a", "https:/cdn.example.com/x"),
            None
        );
        assert_eq!(
            resolve_fetch_redirect("https://example.com/a", "javascript:alert(1)"),
            None
        );
        assert!(
            !is_fetch_redirect(StatusCode::from_u16(304).expect("status builds")),
            "304 is not followed"
        );
        assert!(
            !is_fetch_redirect(StatusCode::from_u16(300).expect("status builds")),
            "300 is not followed"
        );
    }

    /// Stub `HttpClient` recording every fetched URL in order (shared
    /// across the `Fn` handler).
    fn t48_recording_client(
        handler: impl Fn(String) -> gpui_kit::http_client::http::Response<gpui_kit::http_client::AsyncBody>
            + Send
            + Sync
            + 'static,
    ) -> (
        std::sync::Arc<dyn gpui_kit::http_client::HttpClient>,
        std::sync::Arc<std::sync::Mutex<Vec<String>>>,
    ) {
        use gpui_kit::http_client::FakeHttpClient;
        let handler = std::sync::Arc::new(handler);
        let fetched = std::sync::Arc::new(std::sync::Mutex::new(Vec::new()));
        let seen = fetched.clone();
        let client = FakeHttpClient::create(move |req| {
            let seen = seen.clone();
            let handler = handler.clone();
            let uri = req.uri().to_string();
            async move {
                seen.lock().expect("record works").push(uri.clone());
                Ok(handler(uri))
            }
        });
        (client, fetched)
    }

    fn t48_response(
        status: u16,
        location: Option<&str>,
        body: &str,
    ) -> gpui_kit::http_client::http::Response<gpui_kit::http_client::AsyncBody> {
        use gpui_kit::http_client::AsyncBody;
        let mut builder = gpui_kit::http_client::http::Response::builder().status(status);
        if let Some(location) = location {
            builder = builder.header("location", location);
        }
        builder
            .body(AsyncBody::from(body.to_string()))
            .expect("response builds")
    }

    /// Ticket 48 (US-66): a redirect to an internal host is blocked by
    /// the fetch-time re-check — the second hop is never fetched.
    #[test]
    fn t48_fetch_redirect_to_internal_blocked_without_fetch() {
        let (client, fetched) = t48_recording_client(|uri| {
            if uri == "https://example.com/sub.txt" {
                t48_response(302, Some("http://127.0.0.1/evil"), "")
            } else {
                t48_response(200, None, "must never fetch")
            }
        });
        let error = futures::executor::block_on(crate::fetch_subscription_body(
            client,
            "https://example.com/sub.txt",
        ))
        .expect_err("internal redirect blocked");
        assert!(error.contains("internal"), "SSRF cause, got {error}");
        assert_eq!(
            *fetched.lock().expect("read works"),
            vec!["https://example.com/sub.txt".to_string()],
            "the evil hop is never fetched"
        );
    }

    /// Ticket 48 (US-66): a redirect to a public host is followed once
    /// (CDN compat) and its body lands; the entry policy still gates the
    /// first hop, so direct internal URLs never touch the client.
    #[test]
    fn t48_fetch_redirect_to_public_followed_once() {
        let (client, fetched) = t48_recording_client(|uri| {
            if uri == "https://example.com/sub.txt" {
                t48_response(302, Some("https://cdn.example.com/sub.txt"), "")
            } else {
                t48_response(200, None, "cdn-body")
            }
        });
        let body = futures::executor::block_on(crate::fetch_subscription_body(
            client,
            "https://example.com/sub.txt",
        ))
        .expect("public redirect followed");
        assert_eq!(body, "cdn-body");
        assert_eq!(
            *fetched.lock().expect("read works"),
            vec![
                "https://example.com/sub.txt".to_string(),
                "https://cdn.example.com/sub.txt".to_string(),
            ]
        );

        let (client, fetched) = t48_recording_client(|_| t48_response(200, None, "unreachable"));
        let error = futures::executor::block_on(crate::fetch_subscription_body(
            client,
            "http://127.0.0.1/direct",
        ))
        .expect_err("direct internal blocked");
        assert!(error.contains("internal"), "SSRF cause, got {error}");
        assert!(
            fetched.lock().expect("read works").is_empty(),
            "blocked before any fetch"
        );
    }

    /// Ticket 48 (US-66): redirect loops are bounded and location-less
    /// redirects fail loudly instead of hanging or guessing.
    #[test]
    fn t48_fetch_redirect_loop_bounded_and_locationless_loud() {
        let (client, fetched) =
            t48_recording_client(|_| t48_response(302, Some("https://example.com/elsewhere"), ""));
        let error = futures::executor::block_on(crate::fetch_subscription_body(
            client,
            "https://example.com/sub.txt",
        ))
        .expect_err("loop bounded");
        assert!(
            error.contains("too many redirects"),
            "bounded cause, got {error}"
        );
        assert_eq!(
            fetched.lock().expect("read works").len(),
            6,
            "initial plus five hops, then give up"
        );

        let (client, _) = t48_recording_client(|_| t48_response(302, None, ""));
        let error = futures::executor::block_on(crate::fetch_subscription_body(
            client,
            "https://example.com/sub.txt",
        ))
        .expect_err("location-less redirect fails");
        assert!(error.contains("bad redirect"), "loud cause, got {error}");
    }

    // -- Ticket 08: density lock + keyboard + secrets audit ------------------

    /// Ticket 08: frame containment for one painted anchor — the element
    /// paints (see [`assert_painted`]) AND its far edge stays inside the
    /// 1000x700 frame (1px rounding epsilon). Presence alone never proves
    /// "without clipping".
    fn assert_within_frame(cx: &mut VisualTestContext, id: &str) {
        let bounds = cx
            .update(|window, _| window.try_find(id.to_owned()))
            .unwrap_or_else(|| panic!("{id} renders: missing element in completed frame"))
            .bounds();
        assert!(
            bounds.origin.x >= px(0.) && bounds.origin.y >= px(0.),
            "{id} starts inside the frame: {bounds:?}"
        );
        assert!(
            bounds.origin.x + bounds.size.width <= px(1000.) + px(1.),
            "{id} ends inside the frame width: {bounds:?}"
        );
        assert!(
            bounds.origin.y + bounds.size.height <= px(700.) + px(1.),
            "{id} ends inside the frame height: {bounds:?}"
        );
    }

    /// Ticket 08 (a): density lock at the 1000x700 desktop frame — the
    /// command strip, facet bar, three dense rows, inspector, and status
    /// strip all paint inside the frame (no clipping). Command reachability
    /// pins the always-visible strip ids by presence (dedicated buttons
    /// plus menu triggers per `command_strip_all_ids_present`, while the
    /// leading `add-config` — never the clipped end — pins paint);
    /// below-the-fold inspector actions pin presence for the same reason.
    #[gpui_kit::test]
    fn t08_density_lock_paints_without_clipping(cx: &mut TestAppContext) {
        use gpui_kit::component::IndexPath;
        cx.update(gpui_kit::init);
        let mut store = Store::open_in_memory().expect("in-memory store opens");
        let first = store
            .add(row19_seed("Work", "a.example.com", "10801"))
            .expect("seed works");
        let second = store
            .add(row19_seed("Home", "b.example.com", "10802"))
            .expect("seed works");
        let third = store
            .add(row19_seed("Cabin", "c.example.com", "10803"))
            .expect("seed works");
        let (view, cx) = mount_view(store, cx);
        // Select the first row so the inspector has a row to render.
        cx.update(|_, cx| {
            view.update(cx, |view, cx| {
                view.libraries.update(cx, |state, list_cx| {
                    state.delegate_mut().selected = Some(IndexPath::new(0));
                    list_cx.notify();
                });
            });
        });
        cx.run_until_parked();
        paint_frame(cx);
        cx.run_until_parked();
        paint_frame(cx);

        // Command strip: the leading action paints inside the frame (the
        // strip container carries no test anchor; every command pins
        // reachability by presence while `add-config` — the first child,
        // never the clipped end — pins paint). Ticket 10: the strip is 4
        // dedicated buttons plus 4 menu triggers; signal-box 03 restores
        // Import as a persistent fifth (`import-config`); menu items render
        // on open (see `command_strip_all_ids_present`).
        assert_painted(cx, "add-config");
        assert_within_frame(cx, "add-config");
        for id in [
            "add-config",
            "start-selected",
            "stop-selected",
            "test-selected",
            "import-config",
            "library-menu",
            "manage-menu",
            "engine-menu",
            "help-menu",
        ] {
            assert!(
                cx.update(|window, _| window.try_find(id).is_some()),
                "{id} renders in the command strip"
            );
        }
        // Facet bar + pickers paint inside the frame.
        for id in ["facet-bar", "facet-group", "facet-protocol", "facet-status"] {
            assert_painted(cx, id);
            assert_within_frame(cx, id);
        }
        // Three dense rows paint, stacked top-to-bottom, inside the frame.
        for id in [&first.id, &second.id, &third.id] {
            let row = format!("library-row-{id}");
            assert_painted(cx, &row);
            assert_within_frame(cx, &row);
        }
        let tops = cx.update(|window, _| {
            [&first.id, &second.id, &third.id]
                .iter()
                .map(|id| {
                    window
                        .try_find(format!("library-row-{id}"))
                        .expect("dense row paints")
                        .bounds()
                        .origin
                        .y
                })
                .collect::<Vec<_>>()
        });
        assert!(
            tops[1] > tops[0] && tops[2] > tops[1],
            "dense rows stack without overlap: {tops:?}"
        );
        // Inspector paints inside the frame; its tab markers stay stable
        // (presence — they ride as zero-size markers, see the health-pane
        // test) and the row ops stay reachable below the fold.
        assert_painted(cx, "config-detail");
        assert_within_frame(cx, "config-detail");
        assert_painted(cx, "config-endpoints");
        assert_within_frame(cx, "config-endpoints");
        for id in [
            "inspector-tabs",
            "inspector-tab-details",
            "inspector-tab-health",
            "inspector-tab-presets",
            "copy-urls",
            "engine-start",
            "engine-stop",
            "health-test",
            "health-ping",
        ] {
            assert!(
                cx.update(|window, _| window.try_find(id.to_string()).is_some()),
                "{id} renders in the inspector"
            );
        }
        // Status strip paints inside the frame.
        assert_painted(cx, "status-count");
        assert_within_frame(cx, "status-count");
        assert_painted(cx, "status-left");
        assert_within_frame(cx, "status-left");
        for id in [
            "status-center",
            "status-right",
            "engine-status",
            "health-status",
        ] {
            assert!(
                cx.update(|window, _| window.try_find(id.to_string()).is_some()),
                "{id} renders in the status strip"
            );
        }
    }

